  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (219::BIGINT, 'Buena nota, a veces se desvía del tema principal pero es un buen profe y brinda buen apoyo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-10-01T00:00:00+00:00'::TIMESTAMPTZ, 'b5713c42bdf791b6b5491849b995e1155abbcd56cd6dbe8aac6c26cd34b20401'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'el profe está mayor, es aburrido, pero califica suave'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'df3eb932b28033dffacfdacffaab272c5541dc931a1df19c9770fd70019af556'::TEXT, ARRAY[4122]::BIGINT[]),
    (219::BIGINT, 'Es buen profe aunque sus clases son un poco aburridas, a veces se distrae mucho pero si uno le pone atencion puede llegar a entender. Lo unico malo es que califica muy tarde'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '10e67fc29da705cb5341a106b6f8f48d3e402d62b8e270a90566494f6a61ef98'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El profe es muy buena persona, califica bien y deja trabajos en clase faciles. Aveces se distrae un poco durante las clases pero siempre aclara todas las dudas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c2f867d530345d25bb7d75532602e8c737ccb44172dcf720ab0c33325f13b6cb'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El profesor es muy buena gente y sabe explicar pero las clases son muy aburridas y repetitivas, dura mucho en calificar,'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, '44b5c417eb6e001c949aafff86e8e24b5273dd7869c8014c33b494d52a29f088'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'El mae califica muy suave, es bueno si ya llevó el curso más de una vez pero las clases son demasiado aburridas. El mae medio ayuda pero la verdad no tanto y revisa cada 4 meses.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2026-01-04T00:00:00+00:00'::TIMESTAMPTZ, '50d5a4637d72e0850fda2ccec886bcc451f406485f4e5cbb554ff50d2056ae89'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Siempre está dispuesto a explicar de buena manera, muy buena persona, es bastante accesible y califica suave, si acaso se dispersa a veces de la explicación y se practica muy poco, de igual manera las tareas de cátedra ayudan mucho'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '262ed2855eedc25b09df3edbb7dd254b6b971fb370b259ccf3249779e0c21c03'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'El profe Ernesto es excelente calidad de persona, puede aclarar cualquier cosa sin problema. De vez en cuando se dispersa un poco de la explicación pero se puede animar sin problema con este profe, motiva bastante al estudiante y es bastante flexible.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '047794dbcb0ec3e23d8bc038ae243ffc9e09fef5156866835ce67b2b8205db7b'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Muy aburrido, mis compañeros y yo no le entendiamos algunas cosas y califica tarde'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1ec6a01af822ea0972282bad651fee572b593a6b9bce729da07425931ceb9ca8'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Mae la verdad buen profe si se presta atención pero las clases son un bostezo porque le da vueltas al mismo tema y explica varas que no tienen que ver con los temas aveces pero buena nota el viejillo. Ah y tarda demasiado en revisar los examenes'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f6ab889be3c75bae577c787f625c8b539cb78a91a552c30d301d8097969e468b'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Es buena gente y está para ayudar, sabe mucho el problema es que por lo menos yo no supe entenderle a su manera de explicar, no hace ejercicios solo da teoría y teoría, me hubiera ido mejor con otro profesor'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-29T00:00:00+00:00'::TIMESTAMPTZ, 'f8ca16c67aa4891d988f9d85151982fd2535e6343e29dc2f69551668848fd6fd'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'EL profe explica muy bien, es super amable si tiene una duda él sin problemas la responde. Lo único malo es que califica todo a último momento, fuera de eso lo super recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'fea4b5db3bbd01e71c95623a9ff1d69b7f1e7d9b374b89bffb40ea13d0313bfd'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'El profesor es muy amable, pero increíblemente desorganizado. Sus clases se basan en la improvisación y sus informes son innecesariamente largos. A la hora de explicar se pierde muy fácilmente y se va por las ramas, lo cual cansa mucho como estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '83fbea4fb6fa32ac5899c42557e49dc63fd9226e563fdb33597bc6944e918066'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'Es un muy buen profesor, se nota que le apasiona dar clases, apoya a los estudiantes. Lo recomiendo mucho'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '51b14bb353eefb5df96f3227f9f9f20a3ee63266877702b8ec98bbe2691910d8'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Es un profesor muy cómico y amable, si necesita ayuda se la da, es útil hacerse amigo de él, lo malo es que revisa todo a último momento(literlamente el último día).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b41b9640ecfe579b9d965c9bdfe036de4479e4cdabfcbd7de974e3d9660b1f2a'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'En general, el profe me parece muy divertido y muy amigable, vale la pena hacerse amigo de él. En intro, el curso es bastante sencillo, solo hay que encargarse de hacer entregas de presentaciones y proyectos. El único problema es que califica demasiado tarde.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '41152429725e8bc52b90d330df7574e71f4a501bb845e258988c0ee6b0f706fb'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Es buen profe, aveces tiende a enredarse, pero es más por las cosas de la cátedra que están mal redactadas. No califica fuerte, pero si a último minuto. Y es muy buena persona, con mucha disponibilidad para ayudar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, '7aff78cde4e22c0428a4feba243a85054fabcbd3e81d9d2a182da999f722067d'::TEXT, ARRAY[607]::BIGINT[]),
    (219::BIGINT, 'Buena persona, muy calificada en su campo, y hace los laboratorios disfrutables. No tengo ninguna queja, en realidad dejó todo muy claro. Quizás de vez en cuando llega tarde a clases, pero creo que esto no afecta mucho el aprendizaje. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3bd0dbe3c3f9d36b6aea748a38ea0ce0e6515c7c87148afb9ad0473f4fe45cc3'::TEXT, ARRAY[607]::BIGINT[]),
    (219::BIGINT, 'El profe es muy buena nota, le da mucha importancia a la asistencia (Todas las clases pasa asistencias), suele ser un poquillo impuntual y también se enreda con algunos temas. En consulta se aprende más que en clase, le recomiendo que vaya a consulta y de fijo le va bien el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'fc64c6278223ed240d5484436166cb16e65f82090e0de9a613108d7fef79ab21'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Explica todo desde cero, los ejercicios que hace son sencillos de seguir pero hace los suficientes para uno saber cuando utilizar que, envía muchas tareas pero a la hora de estudiar y hacer las tareas y el examen es como un queque. Hay que prestar atención en clase y explica todas las rúbricas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-17T00:00:00+00:00'::TIMESTAMPTZ, '06fd430d7c38539fad6aec041ba679657b335ab1c74d867c25f37c8b68e61d5d'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Algunas clases son interesantes, otras no tanto, con entregar las asignaciones le da casi todos los puntos y siempre da más tiempo si se le pregunta. El profe es desorganizado, pero cumple con lo que dice, y para un curso de 1 crédito es suficiente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '7af7dd49aeb7632ab0384a214c7698bd5c80adc7b985fa0d32ab09293a0f0231'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'Es el profesor más desorganizado del TEC, las clases fueron literalmente ir a ver como el profesor hacía el experimento para después uno hacer el análisis. Al curso no se le saca nada de provecho y con sólo el curso de teoría debería bastar. A día 24 de noviembre, prácticamente no ha revisado nada.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '855248ff9b71bd9f15f78c42e1d6fc6bed61a3e933901881186c5215abc9d371'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'El curso es interesante y el profe es una gran persona. Pero, muy desordenado, planea muchos proyectos, tareas y trabajos "cortos" con plazos super cortos, las calificaciones las sabe hasta el final. Es una lástima, el curso tiene mucho potencial pero se vuelve tedioso por la desorganización.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1331e217b8743e2cabb5bdb4e364b5f705bd6e53fd8c123c075f27f2efb08b91'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'El profesor es muy irresponsable a la hora de entrega de rúbricas, aparte de que las deja a destiempo, es muy confuso con sus instrucciones. Además, es muy impuntual en la asignación de los proyectos. Por la naturaleza del curso hay algunas clases bastante interesantes.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cc45784be31eeb7f0c00417c28f803bfc8ae43359103cb3431962f28a5bd0151'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'El profesor en general es bueno, pero sus clases se hacen muy largas y cuesta prestarle atención por más de 15 minutos. En muchas ocasiones se desvía del tema principal. No volvería a llevar otro curso con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8989f216200f87ca31f0f5547db64e59d231d8a1c3195f9610954ba79da13862'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Es un profe que toma de su tiempo para darnos consejos y motivación a los estudiantes. Hace la clase amena y explica todo lo necesario, tomaría todas las fisicas con él si él los impartiera. No se van a arrepentir de llevar con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '36344c6d2e7ae71d169a02eb11cc633c3202254fd3414a85fdbfc7946e3d6dbc'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Como persona es excelente, siempre busca lo mejor para los estudiantes, generalmente las clases si ocupan las 2 horas. Lo único malo es que es desorganizado, y las instrucciones a los proyectos tampoco son muy claras, fuera de eso todo bien, eso si, no sabra su nota hasta el puro final del curso'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f7f7286ccf79e843daea936e543acfd8c83dbcc1bb76daa2359b58f985b39a4d'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Es muy amable, y se nota que le gusta lo que hace. Sin embargo, es bastante desorganizado y a veces deja proyectos muy largos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f0a8824a65f0d195df05365b6bf52e8306848f341b003d51ee53564dc0c341c0'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'En Óptica se le entiende poco, aunque parezca que se entiende, realmente no mucho. En ambos cursos no espere saber cómo va hasta final de semestre. En Lab es un poco desordenado y a veces se le va la mano con la cantidad de trabajo para los informes. En general, muy buena gente, pero muy desordenado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'f2e02e6734e225d8ab10848f82899c85c1a6c01279dcbd521c7f3bf7042fd5de'::TEXT, ARRAY[4126]::BIGINT[]),
    (219::BIGINT, 'Como persona, el profe es excelente; cae muy bien y es muy humilde. Como profesor también es muy bueno, pero las clases las hace muy largas (bastante) y es algo desordenado al dar las mismas, igual con los trabajos y con las instrucciones: a veces no deja claro y las notas hasta el final de semestre'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'd0b09985c1979ef084dee6312b4d9c678f022ebc9145e7f6b2d3a30adfdc6b7a'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'El profesor es una excelente persona, siempre preocupado por el aprendizaje de los estudiantes. Su talón de Aquiles es lo desorganizado que es, tanto para la organización previa de la clase, como para la entrega de indicaciones de proyectos y para notas como tal. Todo lo revisa al puro final.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'db80155193a0f8f0a03bdd53b5d7738cc23422cfe44cba29fefc63f0b8d6588b'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Buen profe, suele hablar bastante pero lo que dice es muy interesante, debido a los tópicos del curso; sin embargo califica tarde y brinda tarde instrucciones sobre proyectos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '5838482e44630b426e33f6507d4c4a16c3824d12d2346bedd4db84ff9025a73b'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Explica muy bien la materia, además de ayudar al estudiante cuando es necesario. Tiene un gran respeto hacia los estudiantes. El único punto negativo es que es desordenado a la hora de revisar trabajos, por lo que no tendrá idea de su nota hasta el final del curso. Totalemente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'e6eaf5563de1fd0f7a58ffaabf9ce35f28e33285d0f02e93baba28d8404416a5'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'Le interesa que los estudiantes aprendan. Las evaluaciones son justas. El curso parecía algo desordenado al inicio con tantas evaluaciones, pero ya se acomodó al final'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '2acb8f22b4dbf8d18e23cbee669681f779940f2b82c978f0bb1efc9ff700edb2'::TEXT, ARRAY[4127, 607]::BIGINT[]),
    (219::BIGINT, 'Es un muy buen profe, muy respetado y querido por los estudiantes, pero dar laboratorio no es lo de él, deja muchos informes y muy largos que ni él puede revisar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '8933977617b02ce2cce620bdb9003f7848dbca62a3a02672be61937375e21ac0'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'El mae explica bien, es super buena gente, ayuda con fechas si uno lo pide bien pero es increíblemente desordenado, no reviso nada hasta el puro final de semestre y todas las evaluaciones quedaron para el final porque no se pudo organizar en todo el semestre'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '7f59c34bea0e10f03ae28971fa979d1b1d9011b68e9bb7efee2723a1dd865439'::TEXT, ARRAY[4127]::BIGINT[]),
    (219::BIGINT, 'Excelente profesor, uno de los mejores que he tenido. Intro a ingeniería física fue súper interesante y enriquecedor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'da6522db9f0535817a4a7428ed28516f5062bfc27890b26560784246ab62c2be'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Calificó al final del semestre, habla bastante, en presenciales es muy interesante, sabe realmente de lo que habla y es facil de impresionar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '10e3f4aad187b1e795a80588594f2cf5b0ef66e50edf0335d98ebc3bc526d432'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Es un excelente profesor, a veces habla mucho pero lo normal, es muy inspirador y ayuda mucho a sus alumnos, los temas que exponen en ocasiones se vuelven algo interesantes y polémicos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'ac038f085c7f22428d3afd64f3c0783496803b12d424a28d454b30e4e4c70363'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Es buena persona y se nota que quiere ayudar y no perjudicar, pero es demasiado desorganizado, uno ni sabe cómo va porque entrega las notas a final de semestre. Pero sí es muy amable y trata de ayudar a todos. Las clases (tanto virtuales como presenciales) demasiado aburridas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '05188ad52020d4df43a801c5ded9c21ffa8e03f80805cce10ad307607e64c401'::TEXT, ARRAY[631]::BIGINT[]),
    (219::BIGINT, 'Es desorganizado y entrega todas las calificaciones al final del semestre. Sin embargo, para intro es super bueno. Cuando pasamos a virtualidad sus clases se volvieron aburridas, precensialmente son muy intrezantes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'b44826d428a23cbbc1493b6af6538e5e67a1eb46587c3428fc33a1fe651a5886'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Si la clase la hubiera dado otro profe estoy seguro de que sería super aburrida, pero este profe es super simpático y tiene un gran conocimiento general. La verdad es un excelente profesor y una excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '481dcb0bfb2820ea04f774691425f64ec1813009242c21c4131f90f449466b9f'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Un profe muy pura vida que hace que el curso se vuelva súper facil. Se desvía del tema muy fácil pero es porque le gusta hablar. El es súper comprensivo con los estudiantes y siempre va a explicar la materia. Aunque el curso es asíncrónico con la coordinación, él da la clase siempre y hace el lab!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '40a79dbf93577ae57bdc9ee4c094f28ba404cf4e8c6b99ba7c624f506d1a8050'::TEXT, ARRAY[631]::BIGINT[]),
    (219::BIGINT, 'Es un amor de profe, se nota la motivación y el empeño que pone en sus clases. A pesar de que la coordinación hizo el curso asincrónico, él da las clases donde explica mucho más claro cada reporte corto e incluso los hace con nosotros en clase. Hace que el curso se vuelva más fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'b07c0fa3f60aa025332e5e2b926d7b41bd245228e0a48339245a54040cc2db9f'::TEXT, ARRAY[631]::BIGINT[]),
    (219::BIGINT, 'Es un amor de persona, súper paciente. No califica duro, sólo hay que entregar todo y estudiar un toque para pasar. La modalidad con la que da el curso es distinta, entonces hay que hacer más evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7d4c96cf711a7c04721c39628af7ddf96e7cce8f6173fcb0405434d0e044bccb'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El curso se pasa fácil porque no califica muy rudo pero deja demasiadas evaluaciones (el curso vale 1 crédito). Siempre hay que hacer quices antes de entrar a la clase, hay que hacer un trabajo previo al lab y siempre hay que entregar reportes de laboratorio (aparte de los informes).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6175616c408eea7314728b2ed5a80962295e24b0d5b1a4a2b959a58f866a639c'::TEXT, ARRAY[631]::BIGINT[]),
    (219::BIGINT, 'Deja muchas cosas para la casa, siempre hay que leer el libro previo a la clase para no llegar perdido, se va mucho por las ramas. A pesar de todo no es mala opción, deja unas tareas con buen nivel para prepararse para el examen.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '6470376794e49cfbcd0de85b4357235b794b371b539ad2d8e8645f97d83060d1'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Es un profesor excelente. Enseña para la vida y no solo para el examen. Explica la materia de forma clara y los ejemplos que se ven en clase son sacados de examenes. Deja unas tareas bastante útiles para el examen. De lo mejor en la escuela de física.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'a59b24bbf4980b882656c032b62f96f5726bad870a7e9197ddaf7a81ca99257d'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El profe mas tierno qué hay en el TEC, eso si es semana 19 y aún nadie sabe ni cuanto se saco en un pre reporte porque nunca entregó notas ????. Pero es muy buen profe y siempre esta dispuesto a ayudar!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '5fa7cd727ef1f3797c704c35b02c368c78d3ed6d70b885b3eedda114b4104435'::TEXT, ARRAY[631]::BIGINT[]),
    (219::BIGINT, 'Es bueno,deja bastantes tareas que al final son útiles. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f84751dff7898d4f3d7e474ab5a79d2746612fc1c6fc5ec819ed841d7138b082'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'De los mejores profes que he tenido en el TEC. Es un amor de persona, sumamente respetuoso, y profesional. Sabe mucho y expone los temas con un interés increíble. Se nota que le apasiona formar profesionales éticos y comprometidos socialmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a5ddb7e25c5e92d967945561ef6a7ebede0a1c696554fd30e006da22323a1359'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Es un profe es un amor y se preocupa mucho que uno aprenda. Tiene un poco de mala suerte con los proyectores.Deja una tarea por tema que lo prepara a uno súper bien para el examen. Si llega a consulta con gusto lo atenderá y le explicará las cosas las veces que ocupe. Entrega cosas tarde'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Brinda apoyo']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'fc247528cb78a68eb41104741afc27fc4fdd5b2cf2b5bcc46b57d158c285f1de'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Buen profe solo que deja trabajos un poco extensos en muy poco tiempo. Buen profesor y es muy interesado en la materia. Brinda entusiasmo a la hora de explicar, pero en ocaciones tiende a aburrir un poco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '0241af495705584bc20949c25cd83bbf75fa8c093abe66d59b7ffc58d3b2dcd1'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Explica muy bien, califica normal y se preocupa por los estudiantes; lo recomiendo!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'f3cfdfe96ba1554b264fec625709c8848229c55e8d137f00585481abad911621'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El profe expone temas muy interesantes de la física y se nota que le apasiona mucho. A veces se ataranta un poco y no sabe dar instrucciones 100% claras, pero en realidad es un profesor muy bueno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '35c1787de1b8ca966519bb4d58955efdd40c4727aabd52cc0286352f26d036e2'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Excelente profesor y persona. Se preocupa porque los estudiantes realmente entiendan y no solo pasen el curso, hacen falta más como él. Muy claro y las tareas ayudan mucho para el examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1f1a893ff6d9ae312f90c26a5ec9260f36689a899fbc544fa23c79f18f2e85ea'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Se interesa en el estudiante y en el aprendizaje. Se nota su amor por la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '654b57afe97082aba9ab0d04712599b206d53c462d0a889eb10fbdeff7ae0b98'::TEXT, ARRAY[4120]::BIGINT[]),
    (219::BIGINT, 'Excelente persona, ayuda al estudiante y se interesa por su aprendizaje. +1000, recomendado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '439cfd9eb5ca7795d9bf655d8da6db400f1ef2d66553d02e6227d59ef1c8008a'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Se interesa mucho por los estudiantes y es excelente persona, a veces enreda haciendo problemas pero con hacer las tareas que el deja y ver el folleto de Carlos adrian jimenez se pasa bien el curso. Los quices son tareas y siempre deja puntos extra'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a28578520d59446efbcb6fef162fc8d2c9cde81f513de81cda231b6bd2011143'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Muy buen profesor, se preocupa mucho por el aprendizaje de los estudiantes y es bastante asertivo al enseñar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, '8e3958ae327d87c9bebd1727156f79673f15b24468c2296adb226711d43d6188'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, '92b8799e8febc064e5995a2276a9c3d90520d941ce067ca4f94993f3ef63242d'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Recomendado totalmente, disfruta la materia y hace todo lo posible porque el estudiante aprenda y le ayuda a uno en todo lo que puede, hace las clases interesantes. Con hacer las tarea, uno esta preparado para los examenes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'ebde82f7b318bdf8769f07410d7417c90831777bd6638cfa08ad1a8bd5da648c'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '3637ed8da07c5380ca5c505dfa7e99a31f66a80746c89672f5349a01e4df089b'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'El curso es fácil, y aunque las el profe se pierde de vez en cuando se aprende mucho y es muy pasable, con hacer las tareas casi que ya esta listo para el examen. lo único negativo es el tiempo que dura en entregar todo que de verdad es muy lento'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '13e97f183d576df3ad238a96dbc0a810a07d6cef15358ec217728a03619e776e'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Para Física 1 es el mejor y para física 3 enseña muy bien es supe inteligente, llevaría cualquier curso de física con el en especial los laboratorios'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-05-16T00:00:00+00:00'::TIMESTAMPTZ, '597c9e8faf74fe62c7fa0f7fcf5d9310a58b8347dd4a649cad1f9ff169425c3d'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Es de esos profes que de verdad disfrutan dar la materia, explica muy bien aunque tiende a desviarse del tema. Hace quices formativos todas las semanas y se esfuerza por que el estudiante entienda el concepto detrás de la fórmula. Súper recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'c11e0a4b6ba6922b8281c7d25764db0758822c4a88256081ca229a8b0f2353ad'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Uno de los mejores profesores de fisica, ayuda a los estudiantes cuando se lo solicitan y es muy amable, explica muy bien pero aveces se desvia contando otras cosas que no van al caso pero en conclusion es bueno, lo unico es quizas que dura mucho en devolver las tareas y entregar examenes'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '2aa394d883b217be3ba0f363f13e9ba317c9e6ad6736f0002c639fa58496a9d3'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Se podría decir que es un profe ¨bueno¨ comparados con otros profesores de la escuela de física, es súper amble y le explica las veces que sea necesarias aunque no son explicaciones muy claras, los quices son fáciles y deja bastantes tareas con partes extra. la mayoría de personas aprobaron el curso'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, 'cbbbc04e37a2a1427226a439f10caccb396b6a8e46fea4c85a5e942956db0796'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Explicando es claro y deja mucha tarea, lo que es bueno. Lo malo es que en la explicación se desvía y empieza a hablar sobre temas que ni al caso y se pierde mucho tiempo. Aunque los ejercicios que hace en clase son los más simples, las tareas son de complejidad de examen.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'e54596be37231788bc6a34eb21624e6f14ac45202f9f557e6f3bd9475ab8c53a'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Este profesor es demasiado desordenado, siempre dura un montón entregando exámenes, no responde correos, y cosas como las fórmulas del examen se le ocurre subirlas hasta el día antes del mismo. Es un desastre.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '66f053cc6ae0861481c257784d06585832d0dc3c425c5f813353ee5b9a61ae38'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Excelente profe y se preocupa por el aprendizaje de los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'acb96c9a499ac7bd2c26220f188723a7e2acc99d66314af0e46d0a686c3c5edc'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Excelente profesor de los mejores del tec, explica muy bien y es paciente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '87223dd1ea2ad1a2d5e782ae458ff93366d5d7d9ff584a5d1b042e9607e7b224'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'bc1713c7e46761fecef080c05a36f279d9648b0893c5ea9b0f9e801343227647'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Excelente profesor. Se preocupa por que los estudiantes aprendan. Lo recomiendo demasiado, además es muy pura vida. Además deja mucha tarea y no hace quizes, lo cual ayuda demasiado, además en esas tareas deja muchos puntos extra, para que suba bastante la nota.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ce27c103bac6402063185d90c1f78fff387ffe799b6a9baf5ff38764a4bb5df8'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Es buen profe y ordenado, aunque se desvía mucho del tema por bastante tiempo. No hace quices, solo muchas tareas, pero son largas y complicadas. Si se hacen a conciencia, se va muy preparado al examen. Es agradable y claro en la explicación. Evalúa algo duro, pero justo en general'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '9bd76afcde778119d144454918a208b53f0c381a2787cd419b5eb4b02dbe5404'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Muy buen profe, le guesta ayudar a los estudiantes y explica muy bien, califica justo y hace muchas tareas en lugar de quices.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '68d67ee81bf979b922683df3403cddbeeddb45975d142321554ba8dfd62bd63e'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Explica muy bien. Muy buen profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5487f061ba6cd99ddbabe8aea0d9afb25fa357372155077a302c3d3f23d2e748'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '99be9e751a05af3940ece2947431ba7a2365314c9927253a2645f2a9e57aaf1a'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'El mejor profesor de Fisca 1, deja mucha tarea pero necesaria para pasar el curso, ayuda mucho y explica bien, puede que se desvie del tema pero es para aconsejarte y enseñarte sobre la vida y el conocimiento, aprecien eso, es el mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f375e332228401c305dcb70044e47e626373bc48b60b2571fd3419bd324f44e1'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Excelente persona y profesor, se interesa realmente por el aprendizaje de los estudiantes, si califica duro y deja muchas tareas que si las hace a conciencia es casi seguro que pasa el curso. Ayuda bastante a entender en consulta y en clases tiene un problema que a veces se desvía del tema'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '09531619952327ed1542f047eab2961a1449da9a1e2f6b966a20bb4d21d8977c'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Muy buen profe. Explica bien, hace ejemplos... El único "problema" es que casi siempre se desvía del tema por mucho rato.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-03T00:00:00+00:00'::TIMESTAMPTZ, '55af5f5b4f3f81e55fb473465afe1f73d6c678deda302bbaf1973c9773c23761'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Explica bien, se entiende en todas, pero aveces se desvia del tema central'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'fc33ce37be58e0d8bfc73f84f6cfc4b4b5cf4ba38e9bf0a5b4f4026b99c3eebf'::TEXT, ARRAY[604]::BIGINT[]),
    (219::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'c711152c0f27fc063e5cdc32e3cbab9b7e43763638d802474b5890792389a764'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (219::BIGINT, 'Explica muy bien pero califica muy duro!'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '5615f693dffb5014df8c7b8e66b498ef41e4f0af68cfee849b689cc1896b8c8f'::TEXT, ARRAY[922]::BIGINT[]),
    (219::BIGINT, 'Explica muy bien lo que es la fisica, pero a veces se devia mucho de los temas y no da muchos ejemplos! De ahi en fuera todo bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1783e039085947aaf1d85b429adbb8f12045cfbe0c41630c3614ecaed6b80a3a'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (219::BIGINT, 'Simplemente el mejor profesor que tiene la escuela de matemática.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ec08bd2c627589985acf6554aa378f2b98180f5932d4f71f19ee60744026ecd2'::TEXT, ARRAY[1018]::BIGINT[]),
    (219::BIGINT, 'Deja muchas tareas para facilitar comprensión'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'bfbdde6683f7d875600863e1e4fc1263d67fe263d2c3e22dab75d502cc592551'::TEXT, ARRAY[922, 604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
